import { h, render, Component } from 'preact';

import constants from './../constants';

class CreateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {
      file: false,
    };
  }

  componentDidMount() {
  }

  handleCreate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let inputName      = document.querySelector('#input-c-name');
      let inputType      = document.querySelector('#input-c-type');
      let inputLatitude  = document.querySelector('#input-c-latitude');
      let inputLongitude = document.querySelector('#input-c-longitude');

      let name      = inputName.value.trim();
      let type      = inputType.value.trim();
      let latitude  = inputLatitude.value.trim();
      let longitude = inputLongitude.value.trim();

      let json = {};
    
      latitude = parseFloat(latitude);
      longitude = parseFloat(longitude);

      if (!latitude) {
        latitude = 0;
      }

      if (!longitude) {
        longitude = 0;
      }      

      json.name = name;
      json.type = type;
      json.latitude = latitude;
      json.longitude = longitude;
      
      let formData = new FormData();
      let file = self.state.file;
      if (file) {
        formData.append(constants.MARKER_ICON, file);
      }
      
      formData.append('json', JSON.stringify(json));

      self.props.onCreate(formData);
    };

    return fn;
  }

  handleCancel() {
    let self = this;

    let fn = () => {
      if (this.props.onCancel) {
        this.props.onCancel();
      }
    };

    return fn;
  }

  handleChangeFile() {
    let self = this;

    let fn = (evt) => {
      let file = evt.target.files[0];
      if (file) {
        if (file.type != 'image/png') {
          alert('Formato invalido');
          return;
        }

        if (file.size > 10000) {
          alert('La imagen excede el tamaño');
          return;          
        }

        self.state.file = file;
      }      
    };

    return fn;
  }

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <form onSubmit={this.handleCreate()} >

              <div className="form-group">
                <label htmlFor="input-name">Nombre</label>
                <input type="text" className="form-control" id="input-c-name" placeholder="Nombre" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-type">Tipo</label>
                <input type="text" className="form-control" id="input-c-type" placeholder="Tipo" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-latitude">Latitud</label>
                <input type="text" className="form-control" id="input-c-latitude" placeholder="Latitud" />
              </div>

              <div className="form-group">
                <label htmlFor="input-c-longitude">Longitud</label>
                <input type="text" className="form-control" id="input-c-longitude" placeholder="Longitud" />
              </div>              

              <div className="custom-file">
                <input type="file" className="custom-file-input" id="input-c-marker-icon" lang="es" onChange={this.handleChangeFile()} />
                <label className="custom-file-label" for="input-c-marker-icon">Imagen ~75 x 75 px (.png) 10kb</label>
              </div>

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleCancel()}>Cancelar</button>
                <button type="submit" className="btn btn-success">Guardar</button>
              </div>

            </form>
          </div>
        </div>
      </section>
    );
  }
}

export default CreateForm;
