import { h, render, Component } from 'preact';

import constants from './../constants.js';

import Table from './table.jsx';
import CreateForm from './create-form.jsx';
import UpdateForm from './update-form.jsx';

const ENTER = 13;

class Content extends Component {

  constructor() {
    super();

    this.state = {
      items: [],
      item: false,
      updateForm: false,
      search: '',
    };
  }

  componentDidMount() {
    this.getGroups();
  }

  getGroups() {
    let self = this;

    let url = `${constants.URL_SERVER_GROUPS}/list`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ items: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getGroupsForSearch(value) {
    let self = this;

    let url = `${constants.URL_SERVER_GROUPS}/list?search=${value}`;

    let xhr = $.ajax({
      url: url,
      type: constants.METHOD_GET,
      dataType: constants.JSON,
    });

    xhr.done((res, status, response) => {
      if (response.status == constants.STATUS_OK) {
        self.setState({ items: res.docs });

      } else if (response.status == constants.STATUS_ACCEPTED) {
        alert(res.message);
      }
    });

    xhr.fail((res, status, respose) => {
      if (res.responseJSON) {
        let json = res.responseJSON;
        alert(json.message);
      } else {
        alert(constants.MESSAGE_ERROR);
      }
    });
  }

  getGroup() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: `${constants.URL_SERVER_GROUPS}/${json.id}`,
        type: constants.METHOD_GET,
        dataType: constants.JSON
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.getItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.getItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    };

    return fn;
  }

  addGroup() {
    let self = this;

    let fn = (formData) => {
      /*let xhr = $.ajax({
        url: constants.URL_SERVER_GROUPS,
        type: constants.METHOD_POST,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });*/
      let xhr = $.ajax({
        url: constants.URL_SERVER_GROUPS,
        type: constants.METHOD_POST,
        processData: false,
        contentType: false,
        data: formData,
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_CREATED) {
          self.addItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.addItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        $('#create-form').modal('hide');

        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  updateGroup() {
    let self = this;

    let fn = (formData, id) => {
      /*let xhr = $.ajax({
        url: `${constants.URL_SERVER_GROUPS}/${id}`,
        type: constants.METHOD_PUT,
        contentType: constants.APPLICATION_JSON,
        data: JSON.stringify(json)
      });*/

      let xhr = $.ajax({
        url: `${constants.URL_SERVER_GROUPS}/${id}`,
        type: constants.METHOD_PUT,
        processData: false,
        contentType: false,
        data: formData,
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.updateItem(null, res.doc);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.updateItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        $('#update-form').modal('hide');

        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  deleteGroup() {
    let self = this;

    let fn = (json) => {
      let xhr = $.ajax({
        url: `${constants.URL_SERVER_GROUPS}/${json.id}`,
        type: constants.METHOD_DELETE
      });

      xhr.done((res, status, response) => {
        if (response.status == constants.STATUS_OK) {
          self.removeItem(null, json);
        } else if (response.status == constants.STATUS_ACCEPTED) {
          self.removeItem(res.message);
        }
      });

      xhr.fail((res, status, respose) => {
        if (res.responseJSON) {
          let json = res.responseJSON;
          alert(json.message);
        } else {
          alert(constants.MESSAGE_ERROR);
        }
      });
    }

    return fn;
  }

  getItem(err, item) {
    let self = this;

    if (err) {
      alert(err);
      return;
    }

    let form = <UpdateForm item={item} onUpdate={this.updateGroup()} onCancel={this.handleBack()} />;

    this.setState({ updateForm: false }, () => {
      this.setState({ updateForm: form }, () => {
        $('#update-form').modal('show');
      });
    });
  }

  addItem(err, item) {
    $('#create-form').modal('hide');

    if (err) {
      alert(err);
      return;
    }

    let items = this.state.items;
    items.push(item);
    this.setState({ items: items });
  }

  updateItem(err, item) {
    $('#update-form').modal('hide');

    if (err) {
      alert(err);
      return;
    }

    let items = this.state.items;
    for (let i = 0; i < items.length; i++) {
      let id = items[i].id;
      if (item.id == id) {
        items[i] = item;
        break;
      }
    }

    this.setState({ items: items });
  }

  removeItem(err, item) {
    let self = this;

    if (!err) {
      let items = self.state.items;
      for (let i = 0; i < items.length; i++) {
        let id = items[i].id;
        if (item.id == id) {
          items.splice(i, 1);
          break;
        }
      }

      self.setState({ items: items });
    } else {
      alert(err);
    }
  }

  handleCreate() {
    let self = this;

    let fn = () => {
      let inputName = document.querySelector('#input-c-name');
      let inputType = document.querySelector('#input-c-type');

      inputName.value = '';
      inputType.value = '';

      $('#create-form').modal('toggle');
    };

    return fn;
  }

  handleChange() {
    let self = this;

    let fn = (evt) => {
      let value = evt.target.value;
      let space = ' ';
      let re = new RegExp(space, 'g');
      let nil = '';

      value = value.replace(re, nil);
      if (value == '') {
        self.getGroups();
      }
    };

    return fn;
  }

  handleSearch() {
    let self = this;

    let fn = (evt) => {
      if (evt.which == ENTER) {
        evt.preventDefault();
        let search = evt.target.value;
        if (search) {
          if (search !== '') {
            search = search.toLowerCase();
            self.getGroupsForSearch(search);
          }
        }
      }
    };

    return fn;
  }

  handleBack() {
    let self = this;

    let fn = () => {
      $('#create-form').modal('hide');
      $('#update-form').modal('hide');
    }

    return fn;
  }

  render(props, state) {
    return (
      <div>
        <div className="row">

          <div className="col-md-3">
            <h4>Grupos</h4>
          </div>

          <div className="col-md-6">
            <div className="form-group col-md-12">
              <input placeholder="Buscar..." type="text" className="form-control" onInput={this.handleChange()} onKeyPress={this.handleSearch()} />
            </div>
          </div>

          <div className="col-md-3">
            <button type="button" className="btn btn-success" onClick={this.handleCreate()}>
              <span className="glyphicon glyphicon-plus" aria-hidden="true"></span> Nuevo
            </button>
          </div>

        </div>

        <Table items={state.items} onGet={this.getGroup()} onDelete={this.deleteGroup()} />

        <div className="modal fade" id="create-form" tabindex="-1">
          <div className="modal-dialog modal-dialog-centered" role="document">
            <div className="modal-content">
              <div className="modal-header">
                <h4>Registro de Grupo</h4>
                <button type="button" className="close" data-dismiss="modal" aria-label="Close">
                  <span aria-hidden="true">&times;</span>
                </button>
              </div>
              <div className="modal-body">
                <CreateForm onCreate={this.addGroup()} onCancel={this.handleBack()} />
              </div>
            </div>
          </div>
        </div>

        <div className="modal fade" id="update-form" tabindex="-1">
          <div className="modal-dialog modal-dialog-centered" role="document">
            <div className="modal-content">
              <div className="modal-header">
                <h4>Editar Grupo</h4>
                <button type="button" className="close" data-dismiss="modal" aria-label="Close">
                  <span aria-hidden="true">&times;</span>
                </button>
              </div>
              <div className="modal-body">
                {state.updateForm}
              </div>
            </div>
          </div>
        </div>

      </div>
    );

  }
}

render(<Content />, document.getElementById('content-main'));