import { h, render, Component } from 'preact';

import constants from './../constants';

class UpdateForm extends Component {

  constructor(props) {
    super(props);

    this.state = {};
  }

  componentDidMount() {
    let o = this.props.item;
    if (o) {
      let inputName   = document.querySelector('#input-u-name');
      let inputType   = document.querySelector('#input-u-type');
      let inputLatitude = document.querySelector('#input-u-latitude');
      let inputLongitude = document.querySelector('#input-u-longitude');      

      inputName.value   = o.name;
      inputType.value   = o.type;
      inputLatitude.value = o.latitude;
      inputLongitude.value = o.longitude;
    }

  }

  handleUpdate() {
    let self = this;

    let fn = (evt) => {
      evt.preventDefault();

      let inputName = document.querySelector('#input-u-name');
      let inputType = document.querySelector('#input-u-type');
      let inputLatitude = document.querySelector('#input-u-latitude');
      let inputLongitude = document.querySelector('#input-u-longitude');

      let name = inputName.value.trim();
      let type = inputType.value.trim();
      let latitude = inputLatitude.value.trim();
      let longitude = inputLongitude.value.trim();

      let json = {};

      latitude = parseFloat(latitude);
      longitude = parseFloat(longitude);

      if (!latitude) {
        latitude = 0;
      }

      if (!longitude) {
        longitude = 0;
      }

      json.name = name;
      json.type = type;
      json.latitude = latitude;
      json.longitude = longitude;

      let o = this.props.item;
      if (o) {
        let formData = new FormData();
        let file = self.state.file;
        if (file) {
          formData.append(constants.MARKER_ICON, file);
        }

        formData.append('json', JSON.stringify(json));

        self.props.onUpdate(formData, o.id);
      }
    };

    return fn;
  }

  handleCancel() {
    let self = this;

    let fn = () => {
      if (this.props.onCancel) {
        this.props.onCancel();
      }
    };

    return fn;
  }

  handleChangeFile() {
    let self = this;

    let fn = (evt) => {
      let file = evt.target.files[0];
      if (file) {
        if (file.type != 'image/png') {
          alert('Formato invalido');
          return;
        }

        if (file.size > 10000) {
          alert('La imagen excede el tamaño');
          return;
        }

        self.state.file = file;
      }
    };

    return fn;
  }  

  render(props, state) {
    return (
      <section>
        <div className="row">
          <div className="col-md-12">
            <form onSubmit={this.handleUpdate()} >

              <div className="form-group">
                <label htmlFor="input-u-name">Nombre</label>
                <input type="text" className="form-control" id="input-u-name" placeholder="Nombre" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-type">Tipo</label>
                <input type="text" className="form-control" id="input-u-type" placeholder="Tipo" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-latitude">Latitud</label>
                <input type="text" className="form-control" id="input-u-latitude" placeholder="Latitud" />
              </div>

              <div className="form-group">
                <label htmlFor="input-u-longitude">Longitud</label>
                <input type="text" className="form-control" id="input-u-longitude" placeholder="Longitud" />
              </div>

              <div class="custom-file">
                <input type="file" class="custom-file-input" id="input-u-marker-icon" lang="es" onChange={this.handleChangeFile()} />
                <label className="custom-file-label" for="input-u-marker-icon">Imagen ~75 x 75 px (.png) 10kb</label>
              </div>              

              <div className="form-group col-md-12">
                <br />
                <br />
                <button type="button" className="btn btn-warning" onClick={this.handleCancel()}>Cancelar</button>
                <button type="submit" className="btn btn-success">Guardar</button>
              </div>

            </form>
          </div>
        </div>
      </section>
    );
  }
}

export default UpdateForm;
